// CLX Business Signal Detection v2 — Parse Signal Response

const response = $input.item.json;
const lead = $('Split In Batches').first().json;

let rawText = '';
if (response && response.content && Array.isArray(response.content)) {
  rawText = response.content.map(c => c.text || '').join('');
} else if (response && typeof response.content === 'string') {
  rawText = response.content;
}
rawText = rawText.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

let signal;
if (!rawText || rawText.trim() === '') {
  // A missing model response is not a buying signal. Persisting one as
  // 'Manual review needed' put parser output in front of customers as
  // intent -- 284 of 847 signalled leads carried exactly that.
  signal = {
    detected_signal: null,
    growth_stage: 'Established',
    recommended_campaign_type: 'general_outreach',
    signal_confidence: 'Unavailable',
    outreach_timing: 'This Month',
    _signal_error: 'empty_model_response'
  };
} else {
  try {
    signal = JSON.parse(rawText);
  } catch (e) {
    // Same rule for malformed JSON. The error is preserved for triage in
    // _signal_error, never in the customer-facing field.
    signal = {
      detected_signal: null,
      growth_stage: 'Established',
      recommended_campaign_type: 'general_outreach',
      signal_confidence: 'Unavailable',
      outreach_timing: 'This Month',
      _signal_error: 'parse_error: ' + String(e && e.message).slice(0, 200)
    };
  }
}

const now = new Date().toISOString();

return {
  json: {
    id: lead.id,
    // Explicit null, not a cheerful default. 'No signal detected' is a
    // finding; an absent one is an unknown, and the two must not read alike.
    detected_signal: signal.detected_signal || null,
    _signal_error: signal._signal_error || null,
    growth_stage: signal.growth_stage || 'Established',
    recommended_campaign_type: signal.recommended_campaign_type || 'general_outreach',
    signal_confidence: signal.signal_confidence || 'Low',
    outreach_timing: signal.outreach_timing || 'This Month',
    lead_status: 'Signal Detected',
    updated_at: now
  }
};

// CLX Business Signal Detection v2 — Prep Update Signal

const item = $input.item.json;

const body = {
  p_lead_id: item.id,
  p_fields: {
    detected_signal: item.detected_signal,
    growth_stage: item.growth_stage,
    recommended_campaign_type: item.recommended_campaign_type,
    signal_confidence: item.signal_confidence,
    outreach_timing: item.outreach_timing,
    // Only claim a signal was detected when one actually was. Marking a
    // failed parse as 'Signal Detected' is how the funnel counted 284
    // errors as buying intent.
    lead_status: item.detected_signal ? 'Signal Detected' : 'Scored'
  }
};

if (item._signal_error) {
  // leads has no signal_error column and update_lead uses an explicit
  // allowlist, so an extra key would be silently dropped. The execution
  // log is where this is actually visible.
  console.log('SIGNAL PARSE FAILURE:', JSON.stringify({ lead_id: item.id, error: item._signal_error }));
}

console.log('PREP UPDATE:', JSON.stringify({ lead_id: item.id, status: body.p_fields.lead_status, signal: item.detected_signal }));

return { json: { ...item, rpc_body: JSON.stringify(body) } };
